# Shared Workspace Coordinator demo: versioned artifacts + optimistic locking.
WS={}; VERSIONS={}
def write(ns,name,data,expect_version=None):
    key=ns+"/"+name; cur=VERSIONS.get(key,0)
    if expect_version is not None and expect_version!=cur:
        return {"ok":False,"error":"conflict: expected v%d, found v%d"%(expect_version,cur)}
    VERSIONS[key]=cur+1; WS[key]=(data,cur+1)
    return {"ok":True,"version":cur+1}
def read(ns,name,version=None):
    key=ns+"/"+name; data,ver=WS[key]
    return {"version":ver,"data":data}
print(write("job1","report.txt","draft"))
print(write("job1","report.txt","oops-stale",expect_version=0))  # conflict
print(write("job1","report.txt","final",expect_version=1))
print(read("job1","report.txt"))

